CREATE TABLE IF NOT EXISTS private_file_access_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,document_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,ip_address VARCHAR(45) NULL,created_at DATETIME NOT NULL,FOREIGN KEY(document_id) REFERENCES documents(id),FOREIGN KEY(user_id) REFERENCES users(id),INDEX(document_id,created_at),INDEX(user_id,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
ALTER TABLE audit_logs ADD COLUMN organization_id BIGINT UNSIGNED NULL AFTER entity_id, ADD COLUMN project_id BIGINT UNSIGNED NULL AFTER organization_id, ADD COLUMN tournament_id BIGINT UNSIGNED NULL AFTER project_id, ADD COLUMN team_id BIGINT UNSIGNED NULL AFTER tournament_id, ADD INDEX audit_scope (organization_id,project_id,tournament_id,team_id);
